214	template <typename OutputIterator>
215	void extractUris(OutputIterator out, const List* src)
216	{
217	  if (src) {
218	    for (auto& elem : *src) {
219	      const String* uri = downcast<String>(elem);
220	      if (uri) {
221	        out++ = uri->s();
222	      }
223	    }
224	  }
225	}
