261	std::string getHexSha1(const std::string& s)
262	{
263	  unsigned char hash[20];
264	  message_digest::digest(hash, sizeof(hash), MessageDigest::sha1().get(),
265	                         s.data(), s.size());
266	  return util::toHex(hash, sizeof(hash));
267	}
