62	const T* checkParam(const RpcRequest& req, size_t index, bool required = false)
63	{
64	  const T* p = 0;
65	  if (req.params->size() > index) {
66	    if ((p = downcast<T>(req.params->get(index))) == 0) {
67	      throw DL_ABORT_EX(fmt("The parameter at %lu has wrong type.",
68	                            static_cast<unsigned long>(index)));
69	    }
70	  }
71	  else if (required) {
72	    throw DL_ABORT_EX(fmt("The parameter at %lu is required but missing.",
73	                          static_cast<unsigned long>(index)));
74	  }
75	  return p;
76	}
