51	template <typename OutputStream>
52	void encodeValue(const ValueBase* value, OutputStream& o)
53	{
54	  class XmlValueBaseVisitor : public ValueBaseVisitor {
55	  private:
56	    OutputStream& o_;
57	
58	  public:
59	    XmlValueBaseVisitor(OutputStream& o) : o_(o) {}
60	
61	    virtual ~XmlValueBaseVisitor() = default;
62	
63	    virtual void visit(const String& v) CXX11_OVERRIDE
64	    {
65	      o_ << "<value><string>" << util::htmlEscape(v.s()) << "</string></value>";
66	    }
67	
68	    virtual void visit(const Integer& v) CXX11_OVERRIDE
69	    {
70	      o_ << "<value><int>" << v.i() << "</int></value>";
71	    }
72	
73	    virtual void visit(const Bool& boolValue) CXX11_OVERRIDE {}
74	
75	    virtual void visit(const Null& nullValue) CXX11_OVERRIDE {}
76	
77	    virtual void visit(const List& v) CXX11_OVERRIDE
78	    {
79	      o_ << "<value><array><data>";
80	      for (const auto& e : v) {
81	        e->accept(*this);
82	      }
83	      o_ << "</data></array></value>";
84	    }
85	
86	    virtual void visit(const Dict& v) CXX11_OVERRIDE
87	    {
88	      o_ << "<value><struct>";
89	      for (const auto& e : v) {
90	        o_ << "<member><name>" << util::htmlEscape(e.first) << "</name>";
91	        e.second->accept(*this);
92	        o_ << "</member>";
93	      }
94	      o_ << "</struct></value>";
95	    }
96	  };
97	
98	  XmlValueBaseVisitor visitor(o);
99	  value->accept(visitor);
100	}
101	} // namespace
102	
103	namespace {
104	template <typename OutputStream>
105	std::string encodeAll(OutputStream& o, int code, const ValueBase* param)
106	{
107	  o << "<?xml version=\"1.0\"?>"
108	    << "<methodResponse>";
109	  if (code == 0) {
110	    o << "<params>"
111	      << "<param>";
112	    encodeValue(param, o);
113	    o << "</param>"
114	      << "</params>";
115	  }
116	  else {
117	    o << "<fault>";
118	    encodeValue(param, o);
119	    o << "</fault>";
120	  }
121	  o << "</methodResponse>";
122	  return o.str();
123	}
124	} // namespace
125	
126	RpcResponse::RpcResponse(int code, RpcResponse::authorization_t authorized,
127	                         std::unique_ptr<ValueBase> param,
128	                         std::unique_ptr<ValueBase> id)
129	    : param{std::move(param)},
130	      id{std::move(id)},
131	      code{code},
132	      authorized{authorized}
133	{
134	}
135	
136	std::string toXml(const RpcResponse& res, bool gzip)
137	{
138	  if (gzip) {
139	#ifdef HAVE_ZLIB
140	    GZipEncoder o;
141	    o.init();
142	    return encodeAll(o, res.code, res.param.get());
143	#else  // !HAVE_ZLIB
144	    abort();
145	#endif // !HAVE_ZLIB
146	  }
147	  else {
148	    std::stringstream o;
149	    return encodeAll(o, res.code, res.param.get());
150	  }
151	}
152	
153	namespace {
154	template <typename OutputStream>
155	OutputStream& encodeJsonAll(OutputStream& o, int code, const ValueBase* param,
156	                            const ValueBase* id,
157	                            const std::string& callback = A2STR::NIL)
158	{
159	  if (!callback.empty()) {
160	    o << callback << "(";
161	  }
162	  o << "{\"id\":";
163	  json::encode(o, id);
164	  o << ",\"jsonrpc\":\"2.0\",";
165	  if (code == 0) {
166	    o << "\"result\":";
167	  }
168	  else {
169	    o << "\"error\":";
170	  }
171	  json::encode(o, param);
172	  o << "}";
173	  if (!callback.empty()) {
174	    o << ")";
175	  }
176	  return o;
177	}
178	} // namespace
179	
180	std::string toJson(const RpcResponse& res, const std::string& callback,
181	                   bool gzip)
182	{
183	  if (gzip) {
184	#ifdef HAVE_ZLIB
185	    GZipEncoder o;
186	    o.init();
187	    return encodeJsonAll(o, res.code, res.param.get(), res.id.get(), callback)
188	        .str();
189	#else  // !HAVE_ZLIB
190	    abort();
191	#endif // !HAVE_ZLIB
192	  }
193	  else {
194	    std::stringstream o;
195	    return encodeJsonAll(o, res.code, res.param.get(), res.id.get(), callback)
196	        .str();
197	  }
198	}
199	
200	namespace {
201	template <typename OutputStream>
202	OutputStream& encodeJsonBatchAll(OutputStream& o,
203	                                 const std::vector<RpcResponse>& results,
204	                                 const std::string& callback)
205	{
206	  if (!callback.empty()) {
207	    o << callback << "(";
208	  }
209	  o << "[";
210	  if (!results.empty()) {
211	    encodeJsonAll(o, results[0].code, results[0].param.get(),
212	                  results[0].id.get());
213	
214	    for (auto i = std::begin(results) + 1, eoi = std::end(results); i != eoi;
215	         ++i) {
216	      o << ",";
217	      encodeJsonAll(o, (*i).code, (*i).param.get(), (*i).id.get());
218	    }
219	  }
220	  o << "]";
221	  if (!callback.empty()) {
222	    o << ")";
223	  }
224	  return o;
225	}
226	} // namespace
227	
228	std::string toJsonBatch(const std::vector<RpcResponse>& results,
229	                        const std::string& callback, bool gzip)
230	{
231	  if (gzip) {
232	#ifdef HAVE_ZLIB
233	    GZipEncoder o;
234	    o.init();
235	    return encodeJsonBatchAll(o, results, callback).str();
236	#else  // !HAVE_ZLIB
237	    abort();
238	#endif // !HAVE_ZLIB
239	  }
240	  else {
241	    std::stringstream o;
242	    return encodeJsonBatchAll(o, results, callback).str();
243	  }
244	}
